import pytest

from inventory import Inventory


@pytest.fixture
def inv():
    i = Inventory()
    i.add("apple", 1.5, 4)
    i.add("pear", 2.0, 1)
    return i


def test_add_merges_quantity(inv):
    inv.add("apple", 9.9, 2)
    assert inv.items["apple"].qty == 6
    assert inv.items["apple"].price == 1.5


def test_add_rejects_non_positive():
    with pytest.raises(ValueError):
        Inventory().add("x", 1.0, 0)


def test_remove_to_zero_deletes(inv):
    inv.remove("pear")
    assert "pear" not in inv.items


def test_remove_unknown_raises(inv):
    with pytest.raises(KeyError):
        inv.remove("banana")

def test_remove_not_enough_stock(inv):
    # 測試移除數量大於庫存時拋出 ValueError
    with pytest.raises(ValueError, match="not enough stock"):
        inv.remove("pear", 5)


def test_total_value(inv):
    assert inv.total_value() == pytest.approx(8.0)


def test_report_sorted(inv):
    assert inv.report() == "apple: 4 x 1.50\npear: 1 x 2.00"

def test_restock_below_basic(inv):
    # apple (4) >= 3, pear (1) < 3
    # 補貨 pear: 1 + 10 = 11
    restocked = inv.restock_below(threshold=3, amount=10)
    assert restocked == ["pear"]
    assert inv.items["pear"].qty == 11
    assert inv.items["apple"].qty == 4 # apple 不變

def test_restock_below_multiple(inv):
    # apple (4) >= 3, pear (1) < 3
    inv.items["apple"].qty = 2 # 讓 apple 也低於閾值
    # 補貨 apple: 2 + 5 = 7, pear: 1 + 5 = 6
    restocked = inv.restock_below(threshold=3, amount=5)
    # 預期回傳名稱排序後的清單
    assert restocked == ["apple", "pear"]
    assert inv.items["apple"].qty == 7
    assert inv.items["pear"].qty == 6

def test_restock_below_none(inv):
    # 所有品項都足夠
    restocked = inv.restock_below(threshold=10, amount=5)
    assert restocked == []
    # 確保庫存沒有改變
    assert inv.items["apple"].qty == 4
    assert inv.items["pear"].qty == 1
