#include "geometry/registry.hpp"

using namespace geometry;

TEST(RegistryTest, ParsesCircleAndRect) {
    auto c = parse_shape("circle 1");
    EXPECT_EQ(c->name(), "circle");
    auto r = parse_shape("  rect 2 5 ");
    EXPECT_DOUBLE_EQ(r->area(), 10.0);
}

TEST(RegistryTest, ParsesTriangle) {
    // 測試有效三角形
    auto t = parse_shape("triangle 3 4 5");
    EXPECT_EQ(t->name(), "triangle");
    // 3, 4, 5 是直角三角形，面積 = 0.5 * 3 * 4 = 6.0
    EXPECT_NEAR(t->area(), 6.0, 1e-9);

    // 測試等邊三角形
    auto eq_t = parse_shape("triangle 5 5 5");
    // 半周長 s = 7.5. Area = sqrt(7.5 * 2.5 * 2.5 * 2.5) = 25 * sqrt(3) / 4 approx 10.825
