#include "geometry/triangle.hpp"

#include <cmath>
#include <stdexcept>

namespace geometry {

Triangle::Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {
    if (a <= 0 || b <= 0 || c <= 0) {
        throw std::invalid_argument("Triangle sides must be positive");
    }
    // 檢查三角形不等式
    if (a + b <= c || a + c <= b || b + c <= a) {
        throw std::invalid_argument("Sides do not form a valid triangle");
    }
}

std::string Triangle::name() const { return "triangle"; }

// 海龍公式 (Heron's formula)
double Triangle::area() const {
    double s = (a_ + b_ + c_) / 2.0; // 半周長
    return std::sqrt(s * (s - a_) * (s - b_) * (s - c_));
}

}  // namespace geometry
