#include <gtest/gtest.h>

#include "ringbuf.h"

class RingBufTest : public ::testing::Test {
protected:
    void SetUp() override { ASSERT_TRUE(rb_init(&rb, 3)); }
    void TearDown() override { rb_free(&rb); }
    RingBuf rb;
};

TEST(RingBufInit, RejectsZeroCapacity) {
    RingBuf rb;
    EXPECT_FALSE(rb_init(&rb, 0));
}

TEST_F(RingBufTest, PushAndPopInOrder) {
    rb_push(&rb, 1.0);
    rb_push(&rb, 2.0);
    double v = 0;
    ASSERT_TRUE(rb_pop(&rb, &v));
    EXPECT_DOUBLE_EQ(v, 1.0);
    ASSERT_TRUE(rb_pop(&rb, &v));
    EXPECT_DOUBLE_EQ(v, 2.0);
    EXPECT_FALSE(rb_pop(&rb, &v));
}

TEST_F(RingBufTest, OverwritesOldestWhenFull) {
    for (double x : {1.0, 2.0, 3.0, 4.0}) {
        rb_push(&rb, x);
    }
    EXPECT_TRUE(rb_is_full(&rb));
    EXPECT_EQ(rb_size(&rb), 3u);
    double v = 0;
    // 1.0 被覆蓋，應該取出 2.0
    ASSERT_TRUE(rb_pop(&rb, &v));
    EXPECT_DOUBLE_EQ(v, 2.0);
    // 2.0 被取出，剩下 {3.0, 4.0}
    ASSERT_TRUE(rb_pop(&rb, &v));
    EXPECT_DOUBLE_EQ(v, 3.0);
}

TEST_F(RingBufTest, MeanOfFirstValues) {
    rb_push(&rb, 2.0);
    rb_push(&rb, 4.0);
    EXPECT_DOUBLE_EQ(rb_mean(&rb), 3.0);
}

TEST_F(RingBufTest, PeekOldest) {
    rb_push(&rb, 10.0);
    rb_push(&rb, 20.0);

    double peek_val;
    // 應該看到 10.0
    ASSERT_TRUE(rb_peek_oldest(&rb, &peek_val));
    EXPECT_DOUBLE_EQ(peek_val, 10.0);
    // 檢查 count 不變
    EXPECT_EQ(rb_size(&rb), 2u);

    // 再次 peek，應該看到 10.0
    ASSERT_TRUE(rb_peek_oldest(&rb, &peek_val));
    EXPECT_DOUBLE_EQ(peek_val, 10.0);

    // Pop 10.0
    double pop_val;
    ASSERT_TRUE(rb_pop(&rb, &pop_val));
    EXPECT_DOUBLE_EQ(pop_val, 10.0);

    // 再次 peek，應該看到 20.0
    ASSERT_TRUE(rb_peek_oldest(&rb, &peek_val));
    EXPECT_DOUBLE_EQ(peek_val, 20.0);
}

TEST_F(RingBufTest, PeekEmpty) {
    double peek_val;
    // 緩衝區為空
    EXPECT_FALSE(rb_peek_oldest(&rb, &peek_val));
}

TEST_F(RingBufTest, Clear) {
