```c
#include "ringbuf.h"

#include <stdlib.h>
#include <string.h> // 為了使用 memcpy 或其他記憶體操作，雖然這裡主要修正邏輯

bool rb_init(RingBuf *rb, size_t capacity) {
    if (capacity == 0) {
        return false;
    }
    rb->data = malloc(capacity * sizeof(double));
    if (rb->data == NULL) {
        return false;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->count = 0;
    return true;
}

void rb_free(RingBuf *rb) {
    free(rb->data);
    rb->data = NULL;
    rb->capacity = rb->head = rb->count = 0;
}

void rb_push(RingBuf *rb, double value) {
    rb->data[rb->head] = value;
    rb->head = (rb->head + 1) % rb->capacity;
    if (rb->count < rb->capacity) {
        rb->count++;
    }
}

bool rb_pop(RingBuf *rb, double *out) {
    if (rb->count == 0) {
        return false;
    }
    // 計算尾部 (tail) 的位置。
    // 當 count=N, capacity=C, head=H 時，tail = (H - N) mod C
    // (H + C - N) % C 確保結果為正
    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
    *out = rb->data[tail];

    // 由於我們是從頭部（最舊的元素）移除，我們需要更新 count。
    rb->count--;

    // 這裡的關鍵問題是：當我們 pop 後，我們需要確保下一個元素（新的最舊元素）的索引是正確的。
    // 在這個實現中，我們沒有維護一個專門的 tail 指針，而是通過 head 和 count 來推導。
    // 當 count 減少時，我們只是減少了元素數量，head 保持不變（指向下一個寫入位置）。
    // 由於我們沒有移動 data 陣列，這個邏輯是正確的，只要 rb_mean 能夠正確遍歷現有的元素。
    return true;
}

size_t rb_size(const RingBuf *rb) { return rb->count; }

bool rb_is_full(const RingBuf *rb) { return rb->count == rb->capacity; }

double rb_mean(const RingBuf *rb) {
    if (rb->count == 0) {
        return 0.0;
    }

    // 修正點：當使用環形緩衝區時，不能簡單地從 index 0 遍歷 rb->count 次。
    // 我們必須從當前最舊元素的索引（tail）開始，循環遍歷 rb->count 個元素。

    // 計算最舊元素的索引 (tail)
    // tail = (head - count) mod capacity
    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;

    double sum = 0.0;
    for (size_t i = 0; i < rb->count; i++) {
        // 遍歷邏輯：從 tail 開始，循環 i 次
        size_t index = (tail + i) % rb->capacity;
        sum += rb->data[index];
    }

    return sum / (double)rb->count;
}
