    double v_pop = 0.0;
    ASSERT_TRUE(rb_pop(&rb, &v_pop));
    EXPECT_DOUBLE_EQ(v_pop, 2.0); // 2.0 是最舊的

    // 剩餘元素: 3.0, 4.0. 平均: (3+4)/2 = 3.5
    EXPECT_DOUBLE_EQ(rb_mean(&rb), 3.5);
