#include "amr_utils/odom_math.hpp"

#include <cmath>

namespace amr_utils {

double normalize_angle(double angle) {
  return std::fmod(angle + M_PI, 2.0 * M_PI) - M_PI;
}

Pose2D integrate_diff_drive(const Pose2D& pose, double v, double w, double dt) {
  // Midpoint integration: use the heading halfway through the step.
  const double mid = pose.theta + 0.5 * w * dt;
  Pose2D out;
  out.x = pose.x + v * dt * std::cos(mid);
  out.y = pose.y + v * dt * std::sin(mid);
  out.theta = normalize_angle(pose.theta + w * dt);
  return out;
}

Pose2D compose(const Pose2D& a, const Pose2D& b) {
  Pose2D result;
  // x = a.x + cos(a.theta) * b.x - sin(a.theta) * b.y
  result.x = a.x + std::cos(a.theta) * b.x - std::sin(a.theta) * b.y;
  // y = a.y + sin(a.theta) * b.x + cos(a.theta) * b.y
  result.y = a.y + std::sin(a.theta) * b.x + std::cos(a.theta) * b.y;
  // theta = normalize_angle(a.theta + b.theta)
  result.theta = normalize_angle(a.theta + b.theta);
  return result;
}

}  // namespace amr_utils
