#include "amr_utils/odom_math.hpp"

#include <cmath>

namespace amr_utils {

double normalize_angle(double angle) {
  // The standard way to normalize angle to (-pi, pi] is:
  // angle = fmod(angle + pi, 2*pi) - pi;
  // However, if the input angle is very large (e.g., -3pi/2), fmod might behave unexpectedly
  // or the initial addition/subtraction might not bring it into the desired range correctly
  // if the input is far outside [-2pi, 2pi].
  // A more robust approach is to repeatedly add or subtract 2*pi until it's in range.
  double two_pi = 2.0 * M_PI;
  angle = std::fmod(angle, two_pi);
  if (angle <= -M_PI) {
    angle += two_pi;
  } else if (angle > M_PI) {
    angle -= two_pi;
  }
  return angle;
}

Pose2D integrate_diff_drive(const Pose2D& pose, double v, double w, double dt) {
  // Midpoint integration: use the heading halfway through the step.
  const double mid = pose.theta + 0.5 * w * dt;
  Pose2D out;
  out.x = pose.x + v * dt * std::cos(mid);
  out.y = pose.y + v * dt * std::sin(mid);
  out.theta = normalize_angle(pose.theta + w * dt);
  return out;
}

}  // namespace amr_utils
